import Link from "next/link";
import type { VendorView } from "@/modules/vendors/service";
import { vendorCategories, vendorCategoryLabels } from "@/modules/vendors/schema";

export function VendorFilters({ query, events }: { query: Record<string, string>; events: { id: string; name: string }[] }) {
  return <form className="workspace-panel planning-vendor-filters" action="/wedding/vendors"><label>Search saved vendors<input type="search" name="q" defaultValue={query.q ?? ""} maxLength={100} placeholder="Private name or entered contacts" /></label><label>Category<select name="category" defaultValue={query.category ?? ""}><option value="">All categories</option>{vendorCategories.map(c => <option key={c} value={c}>{vendorCategoryLabels[c]}</option>)}</select></label><label>Source<select name="source" defaultValue={query.source ?? ""}><option value="">All sources</option><option value="MANUAL">Manual</option><option value="GOOGLE_PLACES">Google Places</option></select></label><label>Related event<select name="eventId" defaultValue={query.eventId ?? ""}><option value="">All events</option><option value="none">Wedding-wide</option>{query.eventId && query.eventId !== "none" && !events.some(e => e.id === query.eventId) && <option value={query.eventId}>Previous event</option>}{events.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}</select></label><label>Records<select name="status" defaultValue={query.status ?? "active"}><option value="active">Active vendors</option><option value="removed">Removed vendors</option></select></label><button className="button button-primary" type="submit">Apply filters</button><Link className="button button-secondary" href="/wedding/vendors">Clear filters</Link></form>;
}
export function VendorRows({ vendors }: { vendors: VendorView[] }) {
  return <div className="planning-vendor-list"><div className="planning-vendor-table-heading" aria-hidden="true"><span>Vendor name</span><span>Category</span><span>Source</span><span>Contact person</span><span>Related events</span><span>Details</span></div>{vendors.map(v => <article className="planning-vendor-row" key={v.id}><h2><Link href={`/wedding/vendors/${v.id}`}>{v.name}</Link>{v.status === "removed" && <small>Removed</small>}</h2><span className="planning-vendor-category">{vendorCategoryLabels[v.category as keyof typeof vendorCategoryLabels] ?? v.category}</span><span className="planning-vendor-source">{v.source === "GOOGLE_PLACES" ? "Google Places" : "Manual"}</span><div className="planning-vendor-row-contact">{v.contact?.person ?? "Contact not set"}{v.contact?.phone && <small>{v.contact.phone}</small>}</div><div className="planning-vendor-event-tags">{v.events.length ? v.events.map(e => <span key={e.id}>{e.name}{e.available ? "" : " · Unavailable"}</span>) : <span>Wedding-wide</span>}</div><Link className="planning-vendor-view-link" href={`/wedding/vendors/${v.id}`}>View details →</Link></article>)}</div>;
}
